import{_ as t}from"./chunks/viewer.mLrqh1Y4.js";import{_ as a,o as i,c as s,ao as r}from"./chunks/framework.DAbzcW3k.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"TerraScope.jl","tagline":"A 3D viewer for MT, gravity, magnetic and seismic models and data, with geological maps from shapefiles.","actions":[{"theme":"brand","text":"Getting Started","link":"/getting_started"},{"theme":"alt","text":"Inputs","link":"/inputs"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/JuliaGeophysics/TerraScope.jl"}]},"features":[{"title":"One launcher file","details":"You write your file paths and settings in one file. All inputs are optional. The launcher checks each path before it loads the data.","link":"/getting_started"},{"title":"Joint interpretation","details":"Resistivity, density and susceptibility models use the same mesh. Thus you can compare the physical properties cell by cell.","link":"/inputs"},{"title":"Georeferenced overlays","details":"TerraScope reprojects geological maps, measurement stations and seismic profiles into one projected CRS.","link":"/inputs#point-files"},{"title":"Faster startup","details":"Build a custom system image one time. Then the viewer opens much faster.","link":"/startup"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function l(n,e,c,p,h,d){return i(),s("div",null,[...e[0]||(e[0]=[r('<h2 id="What-is-TerraScope.jl?" tabindex="-1">What is TerraScope.jl? <a class="header-anchor" href="#What-is-TerraScope.jl?" aria-label="Permalink to &quot;What is TerraScope.jl? {#What-is-TerraScope.jl?}&quot;">​</a></h2><p>TerraScope.jl is a 3D viewer for geophysical models and data. It shows these datasets together in one 3D view:</p><ul><li><p>MT resistivity models and MT sites</p></li><li><p>Density models and gravity stations</p></li><li><p>Magnetic susceptibility models and magnetic measurements</p></li><li><p>2D seismic sections from SEG-Y files</p></li><li><p>Geological maps from any shapefile: fault traces, lithological contacts, geological units and survey outlines</p></li></ul><p>TerraScope runs on your computer. It uses <a href="https://docs.makie.org/" target="_blank" rel="noreferrer">Makie</a> for the graphics. It is part of the <a href="https://github.com/JuliaGeophysics" target="_blank" rel="noreferrer">JuliaGeophysics</a> ecosystem.</p><p><img src="'+t+'" alt=""></p><div class="tip custom-block"><p class="custom-block-title">Draw your own cross-sections</p><p>Click points on the map to draw a profile in any direction, with as many bends as you need. TerraScope cuts the model along the profile and shows the vertical cross-section in 3D. You can export each cross-section as an image. See <a href="/TerraScope.jl/dev/getting_started#draw-a-cross-section">Draw a cross-section</a>.</p></div><h2 id="Where-do-I-start?" tabindex="-1">Where do I start? <a class="header-anchor" href="#Where-do-I-start?" aria-label="Permalink to &quot;Where do I start? {#Where-do-I-start?}&quot;">​</a></h2><p>Are you new to Julia? Then start at <a href="./getting_started">Getting Started</a>. It shows how to install Julia and how to open the viewer for the first time.</p><p>Do you have Julia already? Then read <a href="./inputs">Inputs</a> to find which files TerraScope can read.</p>',9)])])}const g=a(o,[["render",l]]);export{f as __pageData,g as default};
